local RibbonWeaver = {}
local PRODUCTS = {
    simple_silk_ribbon = { name = "Preprosta svilena pentlja", silkCost = 2, time = 4, cost = 90, happiness = 1, prestige = 1, description = "Preprosta svilena pentlja za dekoracijo." },
    braided_honor_sash = { name = "Pletena častna ruta", silkCost = 3, goldCost = 1, time = 7, cost = 280, happiness = 2, prestige = 4, description = "Pletena častna ruta za viteze." },
    silver_thread_cordon = { name = "Srebronitni cordon", silkCost = 3, silverCost = 1, goldCost = 1, time = 11, cost = 720, happiness = 3, prestige = 9, description = "Srebronitni cordon za visoke častnike." },
    gold_brocade_sash = { name = "Zlatobrokatna ruta", silkCost = 4, goldCost = 2, silverCost = 1, time = 15, cost = 1700, happiness = 4, prestige = 18, description = "Zlatobrokatna ruta za plemstvo." },
    jewel_set_garter_ribbon = { name = "Draguljasta podkolenska pentlja", silkCost = 4, goldCost = 2, jewelCost = 1, time = 19, cost = 3700, happiness = 6, prestige = 32, description = "Red podkolenske pentlje z dragulji." },
    royal_sovereign_sash = { name = "Kraljevska suverena ruta", silkCost = 6, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 8000, happiness = 12, prestige = 60, description = "Suverena kraljevska ruta z biseri." },
}
local BUILDINGS = {
    ribbon_weaving_loom = { name = "Pentljearski statveni tkalništvo", cost = { gold = 280, wood = 160, stone = 100, silk = 4 }, upkeep = 5, qualityBonus = 5 },
    honor_textile_house = { name = "Častna tekstilna hiša", cost = { gold = 1000, wood = 320, stone = 220, silver = 6, silk = 6 }, upkeep = 22, qualityBonus = 18 },
    master_ribbon_atelier = { name = "Mojstrski pentljaški atelje", cost = { gold = 2800, wood = 380, stone = 460, silver = 32, gold = 6 }, upkeep = 64, qualityBonus = 30 },
    sovereign_honors_palace = { name = "Suverena častna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
RibbonWeaver.silkStock = 24; RibbonWeaver.silverStock = 8; RibbonWeaver.goldStock = 6; RibbonWeaver.jewelStock = 4; RibbonWeaver.pearlStock = 4
RibbonWeaver.productStock = {}; RibbonWeaver.buildings = {}; RibbonWeaver.maker = nil; RibbonWeaver.activeMaking = {}; RibbonWeaver.totalProducts = 0; RibbonWeaver.dayTimer = 0
function RibbonWeaver.init() RibbonWeaver.silkStock=24; RibbonWeaver.silverStock=8; RibbonWeaver.goldStock=6; RibbonWeaver.jewelStock=4; RibbonWeaver.pearlStock=4; RibbonWeaver.productStock={}; RibbonWeaver.buildings={}; RibbonWeaver.maker=nil; RibbonWeaver.activeMaking={}; RibbonWeaver.totalProducts=0; RibbonWeaver.dayTimer=0; print("[RibbonWeaver] Royal Ribbon Weaver System initialized (6 products, 4 buildings)") end
function RibbonWeaver.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RibbonWeaver.maker={name=n or ("Pentljaš "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pentljaš najet: %s (spretnost: %d)",RibbonWeaver.maker.name,s),"success") end; return true end
function RibbonWeaver.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RibbonWeaver.build(id) local ok,e=RibbonWeaver.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RibbonWeaver.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RibbonWeaver.getQualityBonus() local b=0; for _,bd in ipairs(RibbonWeaver.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RibbonWeaver.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and RibbonWeaver.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and RibbonWeaver.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RibbonWeaver.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RibbonWeaver.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RibbonWeaver.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RibbonWeaver.buildings==0 then return false,"Potrebno pentljaško tkalsko stroj" end; if not RibbonWeaver.maker then return false,"Potreben pentljaš" end; return true end
function RibbonWeaver.make(pt,qty) qty=qty or 1; local ok,e=RibbonWeaver.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then RibbonWeaver.silkStock=RibbonWeaver.silkStock-d.silkCost*qty end; if d.silverCost then RibbonWeaver.silverStock=RibbonWeaver.silverStock-d.silverCost*qty end; if d.goldCost then RibbonWeaver.goldStock=RibbonWeaver.goldStock-d.goldCost*qty end; if d.jewelCost then RibbonWeaver.jewelStock=RibbonWeaver.jewelStock-d.jewelCost*qty end; if d.pearlCost then RibbonWeaver.pearlStock=RibbonWeaver.pearlStock-d.pearlCost*qty end; local t=d.time; if RibbonWeaver.maker then t=math.max(1,t-math.floor(RibbonWeaver.maker.skill/13)) end; table.insert(RibbonWeaver.activeMaking,{id="ribbon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RibbonWeaver.completeMaking(m) local q=1.0+(RibbonWeaver.getQualityBonus()/100); if RibbonWeaver.maker then q=q+(RibbonWeaver.maker.skill/140) end; q=math.min(2.5,q); RibbonWeaver.productStock[m.productType]=(RibbonWeaver.productStock[m.productType] or 0)+m.quantity; RibbonWeaver.totalProducts=RibbonWeaver.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RibbonWeaver.maker then RibbonWeaver.maker.itemsMade=RibbonWeaver.maker.itemsMade+m.quantity; if math.random()<0.25 then RibbonWeaver.maker.skill=math.min(100,RibbonWeaver.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pentlja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ribbon.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function RibbonWeaver.update(dt) if not _G.state then return end; RibbonWeaver.dayTimer=RibbonWeaver.dayTimer+dt; if RibbonWeaver.dayTimer>=30 then RibbonWeaver.dayTimer=0; for i=#RibbonWeaver.activeMaking,1,-1 do local m=RibbonWeaver.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RibbonWeaver.completeMaking(m); table.remove(RibbonWeaver.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RibbonWeaver.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RibbonWeaver.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RibbonWeaver.getStats() return {silkStock=RibbonWeaver.silkStock,silverStock=RibbonWeaver.silverStock,goldStock=RibbonWeaver.goldStock,jewelStock=RibbonWeaver.jewelStock,pearlStock=RibbonWeaver.pearlStock,productStock=RibbonWeaver.productStock,numBuildings=#RibbonWeaver.buildings,hasMaker=RibbonWeaver.maker~=nil,makerName=RibbonWeaver.maker and RibbonWeaver.maker.name or "—",makerSkill=RibbonWeaver.maker and RibbonWeaver.maker.skill or 0,activeMaking=#RibbonWeaver.activeMaking,totalProducts=RibbonWeaver.totalProducts} end
return RibbonWeaver
